import sys, json, hashlib, glob, os, subprocess, faulthandler
faulthandler.enable(); faulthandler.dump_traceback_later(90, exit=True)
sys.stdin = open('/dev/null')
sha = lambda p: hashlib.sha256(open(p, 'rb').read()).hexdigest()
counts = {'ok': 0, 'bad': 0}
def walk(o, f):
    if isinstance(o, dict):
        paths = [v for v in o.values() if isinstance(v, str) and os.path.isfile(v)]
        hexes = [v for v in o.values() if isinstance(v, str) and len(v) == 64 and all(c in '0123456789abcdef' for c in v)]
        for p in paths:
            if hexes:
                if sha(p) in hexes: counts['ok'] += 1
                else: counts['bad'] += 1; print('BAD', f, p, hexes)
        for v in o.values(): walk(v, f)
    elif isinstance(o, list):
        for v in o: walk(v, f)
for f in glob.glob('benchmark/**/*.json', recursive=True):
    try: walk(json.load(open(f)), f)
    except Exception as e: print('skip', f, e)
print('pins', counts)
base = subprocess.check_output(['git', 'rev-parse', '8cb25137f13b4ba59b0e1543a01b1fa29cffc842^']).decode().strip()
print('base', base)
trans = {}; other = []
def diff(a, b, path):
    if isinstance(a, dict) and isinstance(b, dict):
        for k in sorted(set(a) | set(b)): diff(a.get(k), b.get(k), path + '/' + str(k))
    elif isinstance(a, list) and isinstance(b, list) and len(a) == len(b):
        for i, (x, y) in enumerate(zip(a, b)): diff(x, y, path + '/' + str(i))
    elif a != b:
        if '/expected/' in path:
            if isinstance(a, str) and isinstance(b, str): trans[(a, b)] = trans.get((a, b), 0) + 1
            elif isinstance(a, int) and isinstance(b, int): trans['count'] = trans.get('count', 0) + 1
            else: other.append(path + ' EXP-NONSCALAR')
        else: other.append(path)
for fid in ('library-icon-tests', 'library-specialty', 'vi-actor-core-native-gap'):
    p = 'benchmark/challenges/' + fid + '.json'
    old = json.loads(subprocess.check_output(['git', 'show', base + ':' + p]))
    new = json.load(open(p))
    diff(old, new, fid)
print('expected transitions', {str(k): v for k, v in trans.items()})
print('changes outside expected scalars', len(other), other[:15])
